                  <Box component="ol" sx={{ pl: 2 }}>
                    {currentTask.hints.map((hint, index) => (
                      <Typography 
                        key={index} 
                        component="li" 
                        variant="body1" 
                        sx={{ 
                          mb: 1,
                          lineHeight: 1.6
