              <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center', gap: 2 }}>
                <ButtonGroup variant="contained" disabled={loading}>
                  <Button 
                    color="success" 
                    onClick={() => {
                      if (!code.trim()) {
                        setError('Пожалуйста, введите код перед отправкой');
                        return;
                      }
                      setError(null);
                      handleTaskComplete('completed');
